import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])
    s = input_data[2]

    def max_substring_for_char(target_char):
        left = 0
        count = 0
        max_len = 0
        for right in range(n):
            if s[right] != target_char:
                count += 1
            while count > k:
                if s[left] != target_char:
                    count -= 1
                left += 1
            current_len = right - left + 1
            if current_len > max_len:
                max_len = current_len
        return max_len

    ans_a = max_substring_for_char('a')
    ans_b = max_substring_for_char('b')

    print(max(ans_a, ans_b))

if __name__ == "__main__":
    main()
